	// Post-provider config policy evaluation
	policyDiags := n.EvalPolicy(ctx, unmarkedConfigVal)
	diags = diags.Append(policyDiags)
	if policyDiags.HasErrors() {
		return diags
	}

	return diags
}

// EvalPolicy evaluates the provider policy.
// Contrary to resource policy evaluation, provider policy evaluation is done inline,
// allowing us to block the evaluation of the provider's resources within the graph if the policy fails.
// Provider policies have no support for callback functions, so we do not need to worry about
// them retrieving objects that are not yet available in the state.
func (n *NodeApplyableProvider) EvalPolicy(ctx EvalContext, attrs cty.Value) tfdiags.Diagnostics {
	if ctx.PolicyClient() == nil {
		log.Printf("[DEBUG] No policy client configured, skipping policy evaluation for %s", n.Addr)
		return nil
	}

	_, pvms := attrs.UnmarkDeepWithPaths()
	sensitivePaths, _ := marks.PathsWithMark(pvms, marks.Sensitive)

	result := ctx.PolicyClient().EvaluateProvider(ctx.StopCtx(), policy.EvaluationRequest[*proto.PolicyEvaluateProviderRequest_ProviderMetadata]{
		Target: n.Addr.Provider.Type,
		Attrs: policy.PolicyValue{
			Raw:           attrs,
			RedactedPaths: sensitivePaths,
		},
		Meta: &proto.PolicyEvaluateProviderRequest_ProviderMetadata{
			Name:      n.Addr.Provider.Type,
			Alias:     n.Addr.Alias,
			Namespace: n.Addr.Provider.Namespace,
			Source:    n.Addr.Provider.String(),
			Version:   n.providerVersion(ctx),
		},
	})

func TestContext2Plan_PolicyEvaluation_RedactedPaths(t *testing.T) {
	m := testModuleInline(t, map[string]string{
		"main.tf": `
			terraform {
				required_providers {
					test = {
						source = "hashicorp/test"
						version = "1.0.0"
					}
				}
			}

			variable "current_secret" {
				type      = string
				sensitive = true
			}

			resource "test_resource" "test" {
				schema_sensitive = "from-config"
				current_only     = var.current_secret
			}
		`,
	})

	providerAddr := addrs.NewDefaultProvider("test")
	provider := testProvider("test")
	provider.GetProviderSchemaResponse = getProviderSchemaResponseFromProviderSchema(&providerSchema{
		ResourceTypes: map[string]*configschema.Block{
			"test_resource": {
				Attributes: map[string]*configschema.Attribute{
					"id": {
						Type:     cty.String,
						Computed: true,
					},
					"schema_sensitive": {
						Type:      cty.String,
						Optional:  true,
						Sensitive: true,
					},
					"current_only": {
						Type:     cty.String,
						Optional: true,
					},
					"prior_only": {
						Type:     cty.String,
						Optional: true,
					},
				},
			},
		},
	})

	state := states.BuildState(func(ss *states.SyncState) {
		ss.SetResourceInstanceCurrent(
			mustResourceInstanceAddr("test_resource.test"),
			&states.ResourceInstanceObjectSrc{
				Status:    states.ObjectReady,
				AttrsJSON: []byte(`{"id":"existing","schema_sensitive":"from-state","prior_only":"prior-secret"}`),
				AttrSensitivePaths: []cty.Path{
					cty.GetAttrPath("prior_only"),
				},
			},
			mustProviderConfig(`provider["registry.terraform.io/hashicorp/test"]`),
		)
	})

	policyClient := policy.NewTestMockClient(t)
	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			providerAddr: testProviderFuncFixed(provider),
		},
	})

	plan, diags := ctx.Plan(m, state, &PlanOpts{
		Mode: plans.NormalMode,
		SetVariables: InputValues{
			"current_secret": &InputValue{
				Value:      cty.StringVal("current-secret").Mark(marks.Sensitive),
				SourceType: ValueFromCaller,
			},
		},
		PolicyClient: policyClient,
	})
	tfdiags.AssertNoDiagnostics(t, diags)

	if plan == nil {
		t.Fatal("expected non-nil plan")
	}
	if !policyClient.EvaluateCalled {
		t.Fatal("expected resource policy evaluation to be called")
	}

	if policyClient.EvaluateRequest.Target != "test_resource" {
		t.Fatalf("unexpected policy target %q", policyClient.EvaluateRequest.Target)
	}
	if diff := cmp.Diff(policyClient.EvaluateRequest.Meta, &proto.PolicyEvaluateResourceRequest_ResourceMetadata{
		ProviderType: "test",
		Operation:    proto.Operation_UPDATE,
	}, protocmp.Transform()); diff != "" {
		t.Fatalf("invalid resource metadata: %s", diff)
	}

	wantAttrs := []cty.Path{
		cty.GetAttrPath("schema_sensitive"),
		cty.GetAttrPath("current_only"),
	}
	wantPriorAttrs := []cty.Path{
		cty.GetAttrPath("schema_sensitive"),
		cty.GetAttrPath("prior_only"),
	}

	assertPathsEqual(t, policyClient.EvaluateRequest.Attrs.RedactedPaths, wantAttrs)
	assertPathsEqual(t, policyClient.EvaluateRequest.PriorAttrs.RedactedPaths, wantPriorAttrs)
}

